mapper.select:
select id from lab_notification
where delivery_status = 'FAILED'
  and next_retry_at <= #{now}
order by next_retry_at, id
limit #{limit}

mapper.update:
update lab_notification set read_at = #{readAt}, update_time = #{readAt}
where id = #{notificationId} and receiver_id = #{receiverId}
  and delivery_status = 'SENT' and read_at is null

update lab_notification
set delivery_status = 'FAILED', next_retry_at = #{nextRetryAt},
    last_error_code = #{lastErrorCode}, attempt_count = attempt_count + 1,
    update_by = 'system', update_time = #{updateTime}
where id = #{notificationId}
